// EncodeOrc writes the value to w in the Orc binary format.
func (s Schematic) EncodeOrc(w *orc.Writer) error {
	w.Write(s.Key[:])
	w.String(s.Name)
	w.Bool(s.Nodes != nil)
	if s.Nodes != nil {
		w.Uint32(uint32(len(s.Nodes)))
		for i := range s.Nodes {
			if err := s.Nodes[i].EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	w.Bool(s.Edges != nil)
	if s.Edges != nil {
		w.Uint32(uint32(len(s.Edges)))
		for i := range s.Edges {
			if err := s.Edges[i].EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	w.Bool(s.Configs != nil)
	if s.Configs != nil {
		w.Uint32(uint32(len(s.Configs)))
		for key, val := range s.Configs {
			w.String(key)
			if err := val.EncodeOrc(w); err != nil {
				return err
			}
		}
	}
	if s.Group != nil {
		w.Bool(true)
		w.Write((*s.Group)[:])
	} else {
		w.Bool(false)
	}
	if s.Project != nil {
		w.Bool(true)
		w.Write((*s.Project)[:])
	} else {
		w.Bool(false)
	}
	return nil
}

// DecodeOrc reads the value from r in the Orc binary format.
func (s *Schematic) DecodeOrc(r *orc.Reader) error {
	var err error
	if _, err := r.Read(s.Key[:]); err != nil {
		return err
	}
	if s.Name, err = r.String(); err != nil {
		return err
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Nodes = make([]Node, n)
			for i := range s.Nodes {
				if err = s.Nodes[i].DecodeOrc(r); err != nil {
					return err
				}
			}
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Edges = make([]Edge, n)
			for i := range s.Edges {
				if err = s.Edges[i].DecodeOrc(r); err != nil {
					return err
				}
			}
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			n, err := r.CollectionLen()
			if err != nil {
				return err
			}
			s.Configs = make(map[string]NodeConfig, n)
			for range n {
				var key string
				var val NodeConfig
				if key, err = r.String(); err != nil {
					return err
				}
				if err = val.DecodeOrc(r); err != nil {
					return err
				}
				s.Configs[key] = val
			}
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			var hv group.Key
			if _, err := r.Read(hv[:]); err != nil {
				return err
			}
			s.Group = &hv
		}
	}
	{
		present, err := r.Bool()
		if err != nil {
			return err
		}
		if present {
			var hv project.Key
			if _, err := r.Read(hv[:]); err != nil {
				return err
			}
			s.Project = &hv
		}
	}
	return nil
}

